// 💠 DIAMANT VGT SUPREME STATUS
use serde::{Deserialize,Serialize};use std::collections::BTreeMap;use crate::{tokens::{resolve_theme,ThemeTokens},ThemeError};
#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="kebab-case")]pub enum AppSurface{Writer,Present,GridChart,Forms}
#[derive(Debug,Clone,Serialize,Deserialize)]pub struct FlattenedThemeExport{pub target_format:String,pub native_theme_id:String,pub resolved_tokens:ThemeTokens,pub flattened_properties:BTreeMap<String,String>}
pub fn resolve_for_surface(_surface:AppSurface,workspace:&ThemeTokens,template:Option<&ThemeTokens>,document:Option<&ThemeTokens>,object:Option<&ThemeTokens>)->Result<ThemeTokens,ThemeError>{resolve_theme(workspace,template,document,object)}
pub fn flatten_for_export(target_format:&str,native_theme_id:&str,resolved:&ThemeTokens)->Result<FlattenedThemeExport,ThemeError>{if target_format.is_empty()||target_format.len()>64||native_theme_id.is_empty()||native_theme_id.len()>128{return Err(ThemeError::Invalid("theme-export".into()));}let mut flat=BTreeMap::new();for (k,v) in &resolved.palette{flat.insert(format!("palette.{k}"),v.clone());}for (k,v) in &resolved.semantic_colors{flat.insert(format!("semantic.{k}"),v.clone());}for (k,v) in &resolved.spacing{flat.insert(format!("spacing.{k}"),v.to_string());}Ok(FlattenedThemeExport{target_format:target_format.into(),native_theme_id:native_theme_id.into(),resolved_tokens:resolved.clone(),flattened_properties:flat})}
